from collections import deque
def comps(g,cells):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c] in cells and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; cs=[]
                while q:
                    a,b=q.popleft(); cs.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<R and 0<=y<C and g[x][y] in cells and not seen[x][y]:
                            seen[x][y]=True; q.append((x,y))
                out.append(cs)
    return out
